import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Design principles","description":"","frontmatter":{},"headers":[],"relativePath":"handl/explanation/design-principles.md","filePath":"vendored/handl/explanation/design-principles.md"}`),a={name:`handl/explanation/design-principles.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="design-principles" tabindex="-1">Design principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to “Design principles”">​</a></h1><p>Principles that shape the platform. Language-surface principles are unpublished with the language; these are the ones that govern the kernel, engines, and host.</p><ol><li><strong>Runtime-agnostic.</strong> The platform is independent of any runtime, host, or execution target. Programs can run in browsers, game engines, servers, CLI tools, embedded hardware, or GPUs — the host determines the execution model.</li><li><strong>Declarative.</strong> A document describes <em>what</em> values it contains, not <em>how</em> to compute them.</li><li><strong>Format-agnostic.</strong> Documents can be written in any format that maps to JSON-compatible values.</li><li><strong>Embeddable.</strong> The core is a small kernel designed to be embedded in a host application, not a standalone ecosystem — the Lua/Rhai embedding model, not the Python/Unison model. No runtime owns the codebase, no toolchain must be shipped, no garbage collector is imposed on the host.</li><li><strong>Host provides the world.</strong> The kernel defines no built-in functions, no standard library, no I/O primitives. Everything a program can do is provided by the host: which functions exist, which namespaces are available, what side effects are permitted.</li><li><strong>Content addressing is optional.</strong> Definitions can be identified by hash for deduplication, reproducible builds, and cross-machine sharing — but it is a storage layer, not a constraint.</li><li><strong>Composition over keywords.</strong> The kernel has a small set of primitives. Complex patterns emerge from composition, not from dedicated constructs.</li><li><strong>A language is data.</strong> A <code>Language</code> value is assembled from fragments; engines dispatch on that data. Adding a language construct is a data change — never an engine recompile.</li><li><strong>Tree-shakeable.</strong> Major subsystems are gated by Cargo features. A host enables only the capabilities it needs, and the compiler omits the rest.</li><li><strong>Everything is a plugin.</strong> Every concept is a <code>Plugin</code>: semantics, tooling, targets, the garbage collector, the standard library. A <code>Host</code> is an empty composer that loads kits and plugins and dispatches <code>CapabilityRequest</code>s. Nothing is hard-coded except the composition primitives (<code>Plugin</code>, <code>Host</code>, <code>Operation</code>, <code>Behavior</code>, <code>RuleAcceptor</code>, <code>Contribution</code>). There is no privileged subsystem.</li><li><strong>Evaluation is an operation, not a subsystem.</strong> There is no separate &quot;VM&quot; layer. Evaluation is the <code>Eval</code> operation, served by <code>EvalBehavior</code> rules contributed by plugins — no <code>VirtualMachine</code> trait sits alongside the operation system.</li><li><strong>Garbage collection is a plugin.</strong> A GC strategy is provided by a target or library plugin and selected by the host. A host may run with no GC, a reference-counting GC, a tracing GC, or a region-based collector — all plugin choices.</li><li><strong>Sandboxing is a kit/plugin property.</strong> Whether a program runs sandboxed is determined by which plugins are exposed and which engine runs it, not by a kernel flag.</li><li><strong>Targets are plugins.</strong> A target plugin provides the execution backend (interpreter, compiler, JIT, wasm runtime) by contributing rules. Targets are not a separate layer above plugins — they are plugins.</li></ol>`,3)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};